const LANGUAGE_DATA=[{id:"hindi",name:"Hindi",family:"Indo-Aryan",region:"North & Central India",audio:"assets/audio/hindi.mp3",explanation:"Hindi is the most widely spoken language in India, serving as a lingua franca across much of northern and central India.",difficulty:["easy","medium","hard"]},{id:"bengali",name:"Bengali",family:"Indo-Aryan",region:"West Bengal, Tripura",audio:"assets/audio/bengali.mp3",explanation:"Bengali is known for its rich literary tradition and distinctive rounded script. It is the second most spoken language in India.",difficulty:["easy","medium","hard"]},{id:"tamil",name:"Tamil",family:"Dravidian",region:"Tamil Nadu, Puducherry",audio:"assets/audio/tamil.mp3",explanation:"Tamil is one of the oldest living classical languages in the world with a literary tradition spanning over two millennia.",difficulty:["easy","medium","hard"]},{id:"telugu",name:"Telugu",family:"Dravidian",region:"Andhra Pradesh, Telangana",audio:"assets/audio/telugu.mp3",explanation:'Telugu is often called the "Italian of the East" due to its melodic quality where every word ends in a vowel sound.',difficulty:["easy","medium","hard"]},{id:"marathi",name:"Marathi",family:"Indo-Aryan",region:"Maharashtra",audio:"assets/audio/marathi.mp3",explanation:"Marathi has a unique retroflex consonant system and is the official language of Maharashtra, India's third-largest state by area.",difficulty:["medium","hard"]},{id:"gujarati",name:"Gujarati",family:"Indo-Aryan",region:"Gujarat",audio:"assets/audio/gujarati.mp3",explanation:"Gujarati was the mother tongue of both Mahatma Gandhi and Sardar Patel. Its script lacks the top horizontal line found in Devanagari.",difficulty:["medium","hard"]},{id:"kannada",name:"Kannada",family:"Dravidian",region:"Karnataka",audio:"assets/audio/kannada.mp3",explanation:"Kannada has an unbroken literary history of over a thousand years and uses a script derived from the ancient Brahmi alphabet.",difficulty:["medium","hard"]},{id:"malayalam",name:"Malayalam",family:"Dravidian",region:"Kerala, Lakshadweep",audio:"assets/audio/malayalam.mp3",explanation:"Malayalam is distinguished by its distinctive retroflex sounds and long vowel patterns. It evolved from Middle Tamil around the 9th century.",difficulty:["medium","hard"]},{id:"punjabi",name:"Punjabi",family:"Indo-Aryan",region:"Punjab",audio:"assets/audio/punjabi.mp3",explanation:"Punjabi is unique among Indo-Aryan languages for being tonal. It is written in Gurmukhi script in India and Shahmukhi in Pakistan.",difficulty:["easy","medium","hard"]},{id:"odia",name:"Odia",family:"Indo-Aryan",region:"Odisha",audio:"assets/audio/odia.mp3",explanation:"Odia was designated a Classical Language of India in 2014. Its script features distinctive rounded curves adapted for palm leaf writing.",difficulty:["hard"]},{id:"assamese",name:"Assamese",family:"Indo-Aryan",region:"Assam",audio:"assets/audio/assamese.mp3",explanation:"Assamese serves as the lingua franca of the Brahmaputra Valley and has absorbed significant Tibeto-Burman vocabulary.",difficulty:["hard"]},{id:"urdu",name:"Urdu",family:"Indo-Aryan",region:"Jammu & Kashmir, Delhi, UP",audio:"assets/audio/urdu.mp3",explanation:"Urdu shares a common grammatical base with Hindi but uses Perso-Arabic script and draws heavily on Persian and Arabic vocabulary.",difficulty:["easy","medium"]}],DIFFICULTY_CONFIG={easy:{label:"Easy",rounds:5,poolFilter:a=>a.difficulty.includes("easy"),description:"Common languages with clearly distinct audio samples"},medium:{label:"Medium",rounds:8,poolFilter:a=>a.difficulty.includes("medium"),description:"Similar language families with subtle pronunciation differences"},hard:{label:"Hard",rounds:10,poolFilter:()=>!0,description:"Closely related languages with faster speech and similar phonetics"}};function generateOptions(a,i,e=4){return[...i.filter(i=>i.id!==a.id).sort(()=>Math.random()-.5).slice(0,e-1).map(a=>a.name),a.name].sort(()=>Math.random()-.5)}